		weatherDesc_th = 'ฝน (เพิ่มความเร็วให้สัตว์เลี้ยงธาตุน้ำ ลดความเสียหายจากสัตว์เลี้ยงธาตุไฟ ในตอนท้ายของแต่ละรอบใหญ่จะลบผลกระทบเชิงลบบางส่วนจากสัตว์เลี้ยงทั้งหมด) /n หิมะ (เพิ่มเกราะเป็นสองเท่าสำหรับสัตว์เลี้ยงธาตุน้ำแข็ง สัตว์เลี้ยงทั้งหมดที่ไม่ใช่ธาตุน้ำแข็งจะได้รับความเสียหายธาตุน้ำแข็งในตอนท้ายของแต่ละรอบใหญ่ และอาจถูกแช่แข็ง)',
		weatherDesc_in = 'Hujan (Meningkatkan kecepatan untuk hewan peliharaan elemen Air, mengurangi kerusakan dari hewan peliharaan elemen Api, di akhir setiap ronde besar menghapus beberapa efek negatif dari semua hewan peliharaan) /n Salju (Menggandakan pertahanan untuk hewan peliharaan elemen Es, semua hewan peliharaan yang bukan elemen Es menerima kerusakan elemen Es di akhir setiap ronde besar dan mungkin Beku)',
		weatherDesc_ph = 'Ulan (Pinapataas ang bilis para sa mga Water element na alagang hayop, binabawasan ang pinsala mula sa Fire element na alagang hayop, sa katapusan ng bawat malaking round ay tinatanggal ang ilang negatibong epekto mula sa lahat ng alagang hayop) /n Niyebe (Dobleng depensa para sa mga Ice element na alagang hayop, lahat ng alagang hayop na hindi kabilang sa Ice element ay tumatanggap ng Ice elemental na pinsala sa katapusan ng bawat malaking round at maaaring mag-Frozen)',
		weatherDesc_ma = 'Hujan (Meningkatkan kelajuan untuk haiwan peliharaan elemen Air, mengurangkan kerosakan dari haiwan peliharaan elemen Api, pada akhir setiap pusingan besar menghapuskan sebahagian kesan negatif dari semua haiwan peliharaan) /n Salji (Menggandakan pertahanan untuk haiwan peliharaan elemen Ais, semua haiwan peliharaan yang bukan elemen Ais akan menerima kerosakan elemen Ais pada akhir setiap pusingan besar dan mungkin akan Beku)',
		specialEffDesc = 'Enemy army\'s entire spirit tribe\'s damage reflection effectiveness increases widely /n Our side\'s entire all-kill skill damage increases widely',
		specialEffDesc_vn = 'Địch quân toàn thể tinh linh phản tổn thương hiệu quả tăng lên trên diện rộng /n Bên ta toàn thể tất sát kỹ tổn thương tăng lên trên diện rộng',
		specialEffDesc_en = 'Enemy army\'s entire spirit tribe\'s damage reflection effectiveness increases widely /n Our side\'s entire all-kill skill damage increases widely',
		specialEffDesc_th = 'ประสิทธิภาพการสะท้อนความเสียหายของวิญญาณฝ่ายศัตรูทั้งหมดเพิ่มขึ้นอย่างกว้างขวาง /n ความเสียหายจากสกิลฆ่าทั้งหมดของฝ่ายเราเพิ่มขึ้นอย่างกว้างขวาง',
		specialEffDesc_in = 'Efektivitas pantulan kerusakan seluruh suku roh musuh meningkat secara luas /n Kerusakan keterampilan pembunuhan semua dari pihak kita meningkat secara luas',
		specialEffDesc_ph = 'Epektibo ng pagbalik ng pinsala ng buong espiritu ng kalaban ay tumataas nang malawakan /n Ang pinsala ng lahat ng skill na pumatay sa aming panig ay tumataas nang malawakan',
		specialEffDesc_ma = 'Keberkesanan pantulan kerosakan suku roh musuh meningkat secara meluas /n Kerosakan kemahiran pembunuhan semua pihak kami meningkat secara meluas'
	},
