		palce_ph = 'Yelong Hangin sa Labanan:',
		palce_ma = 'Angin Ais Medan:',
		placeDesc = 'Tù Rem activates Ice-Sealed Duel Arena: /n Prioritizes using ultimate attack on the target for a one-on-one execution duel, /n Also eternally freezes and hunts the target outside of the main one until death, /n The execution and eternal freeze cannot be immunized or dispelled.',
		placeDesc_vn = 'Tù Rem mở ra băng phong giác đấu trường: /n Lựa chọn sử dụng công kích tối cao mục tiêu vì săn giết mục tiêu một đối một quyết đấu, /n Cũng vĩnh cửu đóng băng săn giết mục tiêu bên ngoài toàn bộ mục tiêu, đến chết mới thôi /n Săn giết cùng vĩnh cửu đóng băng không cách nào miễn dịch cùng xua tan',
		placeDesc_en = 'Tù Rem activates Ice-Sealed Duel Arena: /n Prioritizes using ultimate attack on the target for a one-on-one execution duel, /n Also eternally freezes and hunts the target outside of the main one until death, /n The execution and eternal freeze cannot be immunized or dispelled.',
		placeDesc_th = 'ทู เรม เปิดใช้เวทีต่อสู้พันธนาการน้ำแข็ง: /n เลือกใช้การโจมตีสูงสุดกับเป้าหมายเพื่อล่าศัตรูแบบดวลตัวต่อตัว, /n และยังแช่แข็งตลอดกาลพร้อมกับล่าเป้าหมายอื่นนอกเหนือจากเป้าหมายหลักจนกว่าจะตาย, /n การล่าและการแช่แข็งถาวรไม่สามารถต้านทานหรือขจัดได้',
		placeDesc_in = 'Tù Rem mengaktifkan Arena Duel Beku: /n Memilih menggunakan serangan pamungkas pada target dalam duel satu lawan satu untuk memburu, /n Juga membekukan secara permanen dan memburu target lain di luar target utama hingga mati, /n Pemburuan dan pembekuan abadi tidak bisa diimunisasi atau dihilangkan.',
		placeDesc_ph = 'Ina-activate ni Tù Rem ang Ice-Sealed Duel Arena: /n Pinipili ang paggamit ng ultimate attack sa target para sa one-on-one na pagpatay, /n At isinabay ang walang hanggang pagyeyelo at paghabol sa lahat ng target maliban sa pangunahing isa hanggang mamatay, /n Ang pagpatay at walang hanggang freeze ay hindi maaaring ma-immunize o matanggal.',
		placeDesc_ma = 'Tù Rem mengaktifkan Arena Duel Beku: /n Memilih untuk menggunakan serangan utama terhadap sasaran dalam pertarungan satu lawan satu, /n Juga membekukan secara kekal dan memburu sasaran lain di luar sasaran utama sehingga mati, /n Pemburuan dan pembekuan kekal tidak boleh diimunisasi atau dibersihkan.',
		specialEff = {{{6}, 1, 0, '10%'}},
		specialEffDesc = '/n The strongest dragon & Ice Wind duel',
		specialEffDesc_vn = '/n Mạnh nhất chi long & Băng phong quyết đấu',
		specialEffDesc_en = '/n The strongest dragon & Ice Wind duel',
		specialEffDesc_th = '/n มังกรที่แข็งแกร่งที่สุด & การตัดสินใจลมเย็น',
