		specialEffDesc_ph = 'Ang Tatlong Banal na Ibon ay may sarili nilang immunity sa pinsala; /n Ang dalawang panig ay may mga katangian na pumipigil sa pinsala at nagpapataas nito sa malawak na saklaw.',
		specialEffDesc_ma = 'Tiga Burung Suci mempunyai imuniti tersendiri terhadap kerosakan; /n Kedua-dua pihak mempunyai atribut yang menentang kerosakan dan meningkatkannya secara meluas.'
	},
	[80243] = {
		id = 80243,
		gymID = 3,
		hardDegree = 25,
		weight = 1,
		lastJump = 23,
		historyJump = 22,
		weatherDesc = 'Turbulent Airflow (Increases speed for Flying element pets, each turn pets may be Blown Away, non-Flying pets will lose some HP upon landing)',
		weatherDesc_vn = 'Loạn Lưu (Tăng tốc độ cho linh thú hệ bay, mỗi lượt linh thú có khả năng bị Thổi Bay, linh thú không thuộc hệ bay sẽ mất một phần sinh mệnh khi tiếp đất)',
		weatherDesc_en = 'Turbulent Airflow (Increases speed for Flying element pets, each turn pets may be Blown Away, non-Flying pets will lose some HP upon landing)',
		weatherDesc_th = 'กระแสลมปั่นป่วน (เพิ่มความเร็วให้กับสัตว์เลี้ยงธาตุบิน ในแต่ละรอบมีโอกาสที่สัตว์เลี้ยงจะถูกพัดลอย สัตว์เลี้ยงที่ไม่ใช่ธาตุบินจะสูญเสียพลังชีวิตบางส่วนเมื่อแตะพื้น)',
		weatherDesc_in = 'Arus Udara Kacau (Meningkatkan kecepatan untuk hewan peliharaan elemen Terbang, setiap giliran hewan dapat Terhempas, hewan non-Terbang akan kehilangan sebagian HP saat mendarat)',
		weatherDesc_ph = 'Magulong Hangin (Pinapataas ang bilis ng mga Flying element na alagang hayop, bawat turn ay maaaring matangay, ang mga hindi Flying ay mawawalan ng HP kapag lumapag)',
		weatherDesc_ma = 'Aliran Udara Kacau (Meningkatkan kelajuan untuk haiwan peliharaan elemen Terbang, setiap pusingan haiwan mungkin akan Diterbangkan, haiwan bukan elemen Terbang akan kehilangan sebahagian nyawa semasa mendarat)',
		specialEffDesc = 'Hundred Birds Paying Homage to the Phoenix: The Phoenix King will protect the entire team from the effects of chaotic weather. /n Each time the Phoenix King performs an all-kill, it sacrifices 20% of its own life. The blessing of the divine bird covers the entire area and has no limit on the number of times. /n After the Phoenix King dies, all the spirits disperse like birds.  ',
		specialEffDesc_vn = 'Bách Điểu Triều Phượng: Phượng vương sẽ bảo hộ phe bạn toàn thể không nhận loạn lưu thời tiết ảnh hưởng /n Phượng vương mỗi lần tất sát kỹ hi sinh tự thân 20% Sinh mệnh, thần điểu chúc phúc tác dụng phạm vi sẽ bao trùm toàn thể, lại không hạn số lần /n Phượng vương sau khi chết, tất cả tinh linh tan tác như chim muông',
		specialEffDesc_en = 'Hundred Birds Paying Homage to the Phoenix: The Phoenix King will protect the entire team from the effects of chaotic weather. /n Each time the Phoenix King performs an all-kill, it sacrifices 20% of its own life. The blessing of the divine bird covers the entire area and has no limit on the number of times. /n After the Phoenix King dies, all the spirits disperse like birds.  ',
		specialEffDesc_th = 'ร้อยนกเคารพฟีนิกซ์: ราชาฟีนิกซ์จะปกป้องทีมทั้งหมดไม่ให้ได้รับผลกระทบจากสภาพอากาศที่ปั่นป่วน /n ทุกครั้งที่ราชาฟีนิกซ์สังหารทั้งหมด จะเสียสละชีวิตตัวเอง 20% คำอวยพรของนกศักดิ์สิทธิ์ครอบคลุมทั้งพื้นที่และไม่มีจำกัดจำนวนครั้ง /n หลังจากราชาฟีนิกซ์ตาย วิญญาณทั้งหมดจะกระจัดกระจายเหมือนนก',
		specialEffDesc_in = 'Ratusan Burung Menghormati Phoenix: Raja Phoenix akan melindungi seluruh tim dari pengaruh cuaca kacau. /n Setiap kali Raja Phoenix melakukan pembantaian, ia mengorbankan 20% nyawanya sendiri. Berkat burung suci meliputi seluruh area tanpa batas jumlah kali. /n Setelah Raja Phoenix mati, semua roh tercerai-berai seperti burung.  ',
		specialEffDesc_ph = 'Daang Ibon na Sumisamba sa Phoenix: Ang Phoenix King ay poprotektahan ang buong koponan mula sa epekto ng magulong panahon. /n Sa bawat all-kill ng Phoenix King, isinusuko nito ang 20% ng sariling buhay. Ang biyaya ng banal na ibon ay sumasaklaw sa buong lugar at walang limitasyon sa bilang ng beses. /n Pagkatapos mamatay ang Phoenix King, ang lahat ng mga espiritu ay nagkalat tulad ng mga ibon.  ',
		specialEffDesc_ma = 'Ratusan Burung Menghormati Phoenix: Raja Phoenix akan melindungi seluruh pasukan daripada kesan cuaca kacau. /n Setiap kali Raja Phoenix melakukan pembunuhan besar-besaran, dia mengorbankan 20% nyawanya sendiri. Berkat burung suci meliputi seluruh kawasan dan tiada had bilangan kali. /n Selepas Raja Phoenix mati, semua roh bertebaran seperti burung.  '
	},
