		specialEff = {{{7}, 1, 0, '7%'}, {{7}, 17, 0, 1500}, {{7}, 95, 0, 1500}},
		specialEffDesc = '/n Our side limits deployment to 3 Spirits. /n The enemy disregards one spirit during attacks, while teammates in the same spot use our side\'s attack skills. /n Enemies receiving attacks will perform counterattacks.',
		specialEffDesc_vn = '/n Bên ta hạn chế ra trận 3 Cái tinh linh /n Địch quân mặc cho nhất tinh linh lúc công kích, còn lại đồng đội cùng một chỗ sử dụng kỹ năng công kích bên ta /n Địch quân nhận lúc công kích sẽ tiến hành phản kích',
		specialEffDesc_en = '/n Our side limits deployment to 3 Spirits. /n The enemy disregards one spirit during attacks, while teammates in the same spot use our side\'s attack skills. /n Enemies receiving attacks will perform counterattacks.',
		specialEffDesc_th = '/n ฝ่ายเราจำกัดส่งออกสนามรบ 3 วิญญาณ /n ศัตรูไม่สนใจวิญญาณหนึ่งตัวขณะโจมตี ส่วนเพื่อนร่วมทีมที่อยู่ในที่เดียวกันใช้ทักษะโจมตีฝ่ายเรา /n ศัตรูที่ได้รับการโจมตีจะทำการสวนกลับ',
		specialEffDesc_in = '/n Pihak kami membatasi pengiriman 3 Roh ke medan perang /n Musuh mengabaikan satu roh saat menyerang, sementara rekan satu tim di tempat yang sama menggunakan keterampilan serangan dari pihak kami /n Musuh yang menerima serangan akan melakukan serangan balik',
		specialEffDesc_ph = '/n Nililimitahan ng aming panig ang pagpapadala ng 3 Espiritu sa labanan /n Hindi pinapansin ng kalaban ang isang espiritu habang umaatake, habang ang mga kasama sa parehong lugar ay gumagamit ng aming mga kakayahan sa pag-atake /n Ang mga kalaban na tumatanggap ng pag-atake ay magsasagawa ng panlaban',
		specialEffDesc_ma = '/n Pihak kami menghadkan penghantaran 3 Roh ke medan perang /n Musuh mengabaikan satu roh semasa menyerang, manakala rakan sepasukan di tempat yang sama menggunakan kemahiran serangan pihak kami /n Musuh yang menerima serangan akan melakukan serangan balas'
	},
